function validate(input) {
  const [{ Heights = [] }] = input;
  if (Heights.length === 0) return 'Heights needs at least one bar.';
  const ids = new Set();
  let low = Infinity, high = -Infinity;
  for (const [id, height] of Heights) {
    if (id === null) return 'Every bar needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Heights.`;
    ids.add(id);
    low = Math.min(low, id);
    high = Math.max(high, id);
    if (height === null || height < 0) return `Bar ${id} needs a non-negative height.`;
  }
  if (high - low + 1 !== ids.size) return 'The ids must be consecutive integers.';
  return null;
}

