function generate(rand, size) {
  const count = size === 'small' ? 1 + Math.floor(rand() * 8) : 1500;
  const top = size === 'small' ? 5 : 1000;
  const start = rand() < 0.7 ? 1 : 1 + Math.floor(rand() * 50);
  const Heights = [];
  for (let i = 0; i < count; i++) Heights.push([start + i, Math.floor(rand() * (top + 1))]);
  // Store the bars in a shuffled order so nothing may rely on insertion order.
  for (let i = Heights.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Heights[i], Heights[j]] = [Heights[j], Heights[i]];
  }
  return [{ Heights }];
}
